import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/app/templates/";
    private static final String JDBC_URL = System.getenv("JDBC_URL");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String templateName = req.getParameter("template");
        String reportId = req.getParameter("reportId");
        String format = req.getParameter("format");

        if (templateName == null || reportId == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Load template - note: templateName is validated against DB entries
        String templateContent = loadTemplate(templateName);
        if (templateContent == null) {
            resp.sendError(404, "Template not found");
            return;
        }

        // Fetch report data
        Map<String, String> reportData = fetchReportData(reportId);
        if (reportData.isEmpty()) {
            resp.sendError(404, "Report not found");
            return;
        }

        // Perform substitution
        StringSubstitutor sub = new StringSubstitutor(reportData);
        String rendered = sub.replace(templateContent);

        // Format output - supports XML for legacy integrations
        if ("xml".equalsIgnoreCase(format)) {
            resp.setContentType("application/xml");
            resp.getWriter().write(wrapInXml(rendered, reportData));
        } else {
            resp.setContentType("text/html");
            resp.getWriter().write(rendered);
        }
    }

    private String wrapInXml(String body, Map<String, String> data) {
        // Build XML with report metadata - user-controlled values inserted directly
        StringBuilder xml = new StringBuilder();
        xml.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
        xml.append("<report>\n");
        xml.append("  <metadata>\n");
        for (Map.Entry<String, String> entry : data.entrySet()) {
            xml.append("    <").append(entry.getKey()).append(">");
            xml.append(entry.getValue());
            xml.append("</").append(entry.getKey()).append(">\n");
        }
        xml.append("  </metadata>\n");
        xml.append("  <body>").append(body).append("</body>\n");
        xml.append("</report>");
        return xml.toString();
    }

    private String loadTemplate(String templateName) throws IOException {
        // VULNERABILITY: path traversal in template loading
        // No sanitization of templateName before file read
        File templateFile = new File(TEMPLATE_DIR + templateName);
        if (!templateFile.exists()) return null;
        return new String(java.nio.file.Files.readAllBytes(templateFile.toPath()));
    }

    private Map<String, String> fetchReportData(String reportId) {
        Map<String, String> data = new HashMap<>();
        try (Connection conn = DriverManager.getConnection(JDBC_URL);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT field_name, field_value FROM report_fields WHERE report_id = ?")) {
            ps.setString(1, reportId);
            ResultSet rs = ps.executeQuery();
            while (rs.next()) {
                data.put(rs.getString("field_name"), rs.getString("field_value"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return data;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Health check endpoint also serves template listing
        String action = req.getParameter("action");
        if ("list".equals(action)) {
            File dir = new File(TEMPLATE_DIR);
            String[] files = dir.list();
            resp.setContentType("application/json");
            resp.getWriter().write(Arrays.toString(files));
        } else {
            resp.getWriter().write("OK");
        }
    }
}
